        result = self.comp.compress(traj)
        assert isinstance(result, CompressedState)

    def test_compress_trajectory_id_matches(self):
        traj = _make_trajectory(2)
        result = self.comp.compress(traj)
        assert result.trajectory_id == "traj-unit"

