        traj = _make_trajectory(2)
        result = self.comp.compress(traj)
        assert isinstance(result.state_id, str) and len(result.state_id) > 0

    def test_compress_method_is_identity(self):
        traj = _make_trajectory(2)
        result = self.comp.compress(traj)
        assert result.compression_method == "identity"

