from __future__ import annotations

import pytest


@pytest.mark.module_test
class TestSimulatorFlightWorkflow:
    def test_search_then_book_flight(self, mock_sim):
        results = mock_sim.search_flights(
            origin="New York",
            destination="Paris",
            date="2025-06-01",
            num_passengers=1,
        )
        assert len(results) > 0
        first = results[0]
        assert "edge_id" in first

        booking = mock_sim.book_flight(edge_id=first["edge_id"], num_passengers=1)
        assert "booking_ref" in booking
        assert booking.get("status") == "confirmed"

    def test_search_returns_required_keys(self, mock_sim):
        results = mock_sim.search_flights(
            origin="New York",
            destination="Paris",
